const features = [
  'search',
  'analytics',
  'notifications',
  'billing',
  'reporting'
];

function renderFeatureList(items) {
  return items.map((item, index) => `${index + 1}. ${item.toUpperCase()}`).join('\n');
}

function expensiveBanner(title) {
  const chars = title.split('');
  let out = '';
  for (let i = 0; i < 2000; i++) {
    out = chars.map((char, idx) => String.fromCharCode(char.charCodeAt(0) + (idx % 2))).join('');
  }
  return out;
}

const output = [
  'Demo App',
  expensiveBanner('build engineer'),
  renderFeatureList(features)
].join('\n\n');

console.log(output);

