const start = process.hrtime.bigint();
const srcPath = path.join(__dirname, 'src', 'app.js');
const distDir = path.join(__dirname, 'dist');
const cacheDir = path.join(__dirname, '.cache');
const outPath = path.join(distDir, 'bundle.js');
const cacheMetaPath = path.join(cacheDir, 'build-meta.json');

function ensureDir(dir) {
 if (!fs.existsSync(dir)) {
  fs.mkdirSync(dir, { recursive: true });
 }
}

function optimizedTransform(source) {
 return source
  .split('\n')
  .map((line) => line.replace(/\s+$/g, ''))
  .join('\n')
  .trimEnd() + '\n';
}

ensureDir(distDir);
ensureDir(cacheDir);

const source = fs.readFileSync(srcPath, 'utf8');
const sourceHash = crypto.createHash('sha1').update(source).digest('hex');
let cacheHit = false;

if (fs.existsSync(cacheMetaPath)) {
 const previous = JSON.parse(fs.readFileSync(cacheMetaPath, 'utf8'));
 if (previous.sourceHash === sourceHash && fs.existsSync(outPath)) {
  cacheHit = true;
 }
}

if (!cacheHit) {
